ACTS.spsave=function(){var s=S.sa;s.ns='saving';render();pfFoc('sp-nt');setTimeout(function(){s.ns=S.mode==='ok'?'saved':'err';render()},500)};
SUBS['f-fin']=function(){var s=S.sa;if(s.busy)return;s.eM=!s.mood;s.eN=s.note.trim().length<10;if(s.eM||s.eN){render();pfFoc(s.eM?'spd-x':'sp-note');if(s.eM){var r=document.querySelector('input[name=sp-mood]');if(r)r.focus()}return}
 s.busy=true;s.eEnd=false;render();pfFoc('sp-est');setTimeout(function(){s.busy=false;if(S.mode!=='ok'){s.eEnd=true;render();pfFoc('sp-est');return}S.sa=spBlank();location.hash='#panel_pro';toast(t('sp_ended'))},700)};
var spTm=null;
/* ---------- entradas de texto y cambios (sin volver a pintar para no perder el foco) ---------- */
function pfCt(id,txt,max){var e=document.getElementById(id);if(e)e.textContent=max?t('rv_max',{n:max})+' · '+t('rv_ct',{c:txt.length,n:max}):''}
document.addEventListener('input',function(e){var el=e.target,id=el.id;
 if(S.route==='facilitacion_revision'&&(id==='fr-obs'||id==='fr-lim')){var k=id.slice(3),f=S.fr;if(!f.obs&&!f.lim&&el.value)f.loc=S.lang;f[k]=el.value;pfCt(id+'-c',el.value,RVL[k])}
 else if(S.route==='mis_revisiones'&&id==='mr-txt'){S.mr.txt=el.value;pfCt('mr-c',el.value,RVL.reason)}
 else if(S.route==='panel_pro'&&id==='gu-txt'){S.pn.guTxt=el.value;var c=document.getElementById('gu-c');if(c)c.textContent=t('gu_min')+' · '+t('gu_ct',{n:el.value.length})}
 else if(S.route==='paciente_pro'){if(id==='nt-txt')S.fi.ntx=el.value;else if(id==='nt-edit')S.fi.etx=el.value;else if(id==='sc-dt')S.fi.sdt=el.value}
 else if(S.route==='sala_pro'){var s=S.sa;if(id==='sp-nt'){s.nt=el.value;s.ns='idle';var m=document.getElementById('sp-ns');if(m)m.textContent=t('sp_nIdle');clearTimeout(spTm);if(el.value.trim())spTm=setTimeout(function(){if(S.route!=='sala_pro')return;s.ns='saving';var q=document.getElementById('sp-ns');if(q)q.textContent=t('sp_saving');setTimeout(function(){s.ns=S.mode==='ok'?'saved':'err';if(S.route==='sala_pro'&&!s.dlg)render();else{var z=document.getElementById('sp-ns');if(z)z.textContent=t(s.ns==='saved'?'sp_saved':'sp_nerr')}},500)},2000)}
  else if(id==='sp-note'){s.note=el.value;var n=document.getElementById('sp-nc');if(n)n.textContent=t('sp_noteMin')+' · '+t('sp_noteCt',{n:el.value.length})}}});
document.addEventListener('change',function(e){var el=e.target;
 if(S.route==='facilitacion_revision'&&el.id&&el.id.indexOf('fr-ev-')===0){var f=S.fr,r=el.value,i=f.ev.indexOf(r);if(el.checked&&i<0)f.ev.push(r);else if(!el.checked&&i>-1)f.ev.splice(i,1)}
 else if(S.route==='paciente_pro'&&el.name==='sc-dur')S.fi.sdur=+el.value;
 else if(S.route==='sala_pro'&&el.name==='sp-mood'){S.sa.mood=+el.value;S.sa.eM=false;var m=document.getElementById('sp-em');if(m)m.remove()}});
